</input>
<input>
1000000000000
</input>
</sample_inputs>

Here is the source code:
<source_code>
#include <bits/stdc++.h>
#define fi first
#define se second
#define gc getchar() //(p1==p2&&(p2=(p1=buf)+fread(buf,1,1<<20,stdin),p1==p2)?EOF:*p1++)
#define mk make_pair
#define pii pair<int, int>
#define pll pair<ll, ll>
#define pb push_back
#define IT iterator
#define V vector
#define TP template <class o>
#define TPP template <typename t1, typename t2>
#define SZ(a) ((int)a.size())
#define all(a) a.begin(), a.end()
#define rep(i, a, b) for (int i = a, i##ed_ = b; i <= i##ed_; i++)
#define REP(i, a, b) for (int i = b, i##st_ = a; i >= i##st_; i--)
#define FOR(i, n) rep(i, 1, n)
#define debug(x) cerr << #x << ' ' << '=' << ' ' << x << endl
using namespace std;
typedef double db;
typedef unsigned ui;
typedef long long ll;
typedef long double ld;

// char buf[1 << 20],*p1=buf,*p2=buf;
TP void qr(o& x) {
    char c = gc;
    x = 0;
    int f = 1;
    while (!isdigit(c)) {
        if (c == '-')
            f = -1;
        c = gc;
    }
    while (isdigit(c))
        x = x * 10 + c - '0', c = gc;
    x *= f;
}
template <class o, class... O> void qr(o& x, O&... y) { qr(x), qr(y...); }
TP void qw(o x) {
    if (x < 0)
        putchar('-'), x = -x;
    if (x / 10)
        qw(x / 10);
    putchar(x % 10 + '0');
}
TP void pr1(o x) { qw(x), putchar(' '); }
template <class o, class... O> void pr1(o x, O... y) { pr1(x), pr1(y...); }
TP void pr2(o x) { qw(x), putchar(10); }
template <class o, class... O> void pr2(o x, O... y) { pr2(x), pr2(y...); }
TP bool cmax(o& x, o y) { return (x < y ? x = y, 1 : 0); }
TP bool cmin(o& x, o y) { return (x > y ? x = y, 1 : 0); }

const int mod = 998244353, mod2 = 1e9 + 7;
TPP void ad(t1& x, t2 y) { (x += y) >= mod && (x -= mod); }
TPP void dl(t1& x, t2 y) { (x -= y) < 0 && (x += mod); }

const int N = 1e6 + 10, B = 1e6;
ll n, x, y, ans; 

V<int> t[7]; int s[7], cnt;

inline int val(int x) {
    if(x < 0) return x + mod;
    return x;
}

void dfs(int x, int y) {
    ++cnt; int z = val(cnt - y);
    t[x].pb(z); s[x] = (s[x] + z) % mod2;
    if(x == 6) return ;
    rep(i, 0, 9) dfs(x + 1, y * 10 + i);
}

void DFS(int x, ll y) {
    if(y > n) return ;
    if(y * 10 * B > n && (y + 1) * B - 1 <= n) {
        ll u = y;
        rep(i, 0, 6) {
            ll w = val(cnt - u);
            ans += w * t[i].size() + s[i];
            ans -= (t[i].end() - lower_bound(all(t[i]), mod - w)) * (ll)mod;
            u = u * 10 % mod;
        }
        ans %= mod2; ad(cnt, 1111111);
        return; 
    }
    if(x) ad(cnt, 1), ans += val(cnt - y % mod);
    rep(i, !x, 9) DFS(x + 1, y * 10 + i);
}

void solve() {
    qr(n);
    dfs(0, 0);
    rep(i, 0, 6) sort(all(t[i]));
    cnt = 0; DFS(0, 0); ans = (ans % mod2 + mod2) % mod2; pr2(ans);
}

int main() {
#ifndef ONLINE_JUDGE
    clock_t start_time = clock();
#endif
    int T = 1;
    // qr(T);
    while (T--)
        solve();
    return 0;
}
</source_code>
